body { font-family: system-ui, sans-serif; padding: 12px; }
body.dark { background: #0d1c2e; color: #e4eefa; }
li.done { text-decoration: line-through; color: gray; }

const names = ["An", "Bình", "Chi"];
const list = document.getElementById("list");

for (const name of names) {
  const li = document.createElement("li");   // tạo phần tử
  li.textContent = name;                      // gán chữ
  li.classList.add("friend");                 // thêm class
  list.appendChild(li);                       // gắn vào cây DOM
}

document.getElementById("theme").addEventListener("click", () => {
  document.body.classList.toggle("dark");     // bật/tắt class
});

